<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { showToast } from 'vant'; import { createApiClient } from '../api/client'; import { HttpApiClient } from '../api/http-client'; import { createIdempotencyKey } from '../api/idempotency'; import type { Order } from '../api/contracts'
const route=useRoute(); const client=createApiClient(); const order=ref<Order|null>(null); const scores=ref([0,0,0,0]); const targetUserId=ref(''); const comment=ref(''); const anonymous=ref(false); const submitting=ref(false); const loading=ref(true); const error=ref(''); const labels=['守时','沟通','安全','礼貌']; const currentUserId=()=>HttpApiClient.currentUserId
async function load(){loading.value=true;error.value='';try{order.value=await client.getOrder(String(route.params.id));const self=currentUserId();targetUserId.value=order.value.members?.find(member=>member.userId!==self)?.userId??order.value.members?.[0]?.userId??''}catch(caught){error.value=caught instanceof Error?caught.message:'订单加载失败'}finally{loading.value=false}}
async function submit(){if(!targetUserId.value){error.value='暂无可评价的同行';return}if(scores.value.some(score=>score<1||score>5)){error.value='请完成全部评价后再提交';return}submitting.value=true;error.value='';try{await client.submitReview({fareOrderId:String(route.params.id),targetUserId:targetUserId.value,dimensions:{punctuality:scores.value[0],communication:scores.value[1],safety:scores.value[2],fairness:scores.value[3]},comment:comment.value,anonymous:anonymous.value},createIdempotencyKey());showToast('评价已提交')}catch(caught){error.value=caught instanceof Error?caught.message:'提交失败，请稍后重试'}finally{submitting.value=false}}
onMounted(load)
</script>
<template><main class="page"><div class="eyebrow">同行反馈</div><h1>评价</h1><div v-if="loading" class="async-state">正在加载可评价同行…</div><div v-else-if="error&&!order" class="async-state state-error" role="alert">{{error}} <button class="secondary-button" @click="load">重新加载</button></div><div v-else class="detail-card"><label>评价对象<select v-model="targetUserId"><option v-for="member in order?.members" :key="member.userId" :value="member.userId">{{member.userId}}</option></select></label><label v-for="(label,index) in labels" :key="label">{{label}}<input v-model.number="scores[index]" type="number" min="1" max="5" /></label><label>补充说明<textarea v-model="comment" rows="3"></textarea></label><label><input v-model="anonymous" type="checkbox" /> 匿名评价</label><p v-if="error" class="form-error" role="alert">{{error}}</p><button class="primary-button" :disabled="submitting||Boolean(order?.disputed||order?.settlementLocked)" @click="submit">{{submitting?'提交中…':'提交评价'}}</button></div></main></template>
